  deep=[('Reklamdan gelen konuşmayı kaçırmamak', 'Click-to-WhatsApp reklamlarında kişi sohbet başlattığında hızlı yanıt çok önemlidir. Çalışma saatleri dışında karşılama mesajı, sık sorulara hazır yanıtlar ve yoğun dönemlerde ekibin nasıl paylaşılacağı baştan planlanmalıdır. Aksi halde reklam bütçesi karşılıksız kalabilir.'), ('Yayın mesajları ve izin sınırları', 'Müşterilere izinsiz toplu mesaj göndermek hem platform kuralları hem de mevzuat açısından risklidir; hesabın kısıtlanmasına yol açabilir. Yalnızca izin veren kişilere yayın yapar, vazgeçme yolunu her mesajda sunarız. Hukuki değerlendirme için uzmanınıza danışmanızı öneririz.'), ('Uygulama mı, API mi?', 'Küçük işletmeler WhatsApp Business uygulamasıyla başlayabilir. Birden fazla temsilci, otomasyon veya toplu şablon mesaj gerekiyorsa API gerekebilir ve ek maliyet doğurur. İhtiyacı birlikte değerlendirir, gerekirse WhatsApp Business API hizmetimizle birleştiririz.')],
  cardsH='WhatsApp pazarlamada hangi işleri yapıyoruz?',
  cards=[('Click-to-WhatsApp reklamı', 'Reklam hedefi, kitle ve karşılama mesajını hazırlar, başlayan konuşmaları kayda alırız.'), ('İzinli yayın planı', 'İzin toplama ve vazgeçme düzenini kurar, yayın içeriklerini ve takvimini hazırlarız.'), ('Katalog ve ürün sunumu', 'WhatsApp kataloğunuzu düzenler, sık sorulan ürünler için hazır yanıt ve görsel hazırlarız.'), ('Destek ve satış akışı', 'Yanıt sürelerini, devir kurallarını ve sipariş alma adımlarını belirleriz.')],
  tools=[['Meta Reklam Yöneticisi', 'Reklam kaç konuşma başlattı?'], ['WhatsApp Business uygulaması veya API paneli', 'Konuşmalar ve mesajlar nasıl yönetiliyor?'], ['WhatsApp kataloğu', 'Ürünler müşteriye doğru gösteriliyor mu?'], ['Konuşma ve satış tablosu', 'Hangi konuşma siparişe dönüştü?'], ['İzin kayıt listesi', 'Kimden hangi tarihte izin alındı?']],
  toolsText='Konuşmaların siparişe dönüşümü reklam panelinde tam görünmeyebilir; bu nedenle basit bir konuşma ve satış tablosu veya CRM kaydıyla takip ederiz. İzin kayıtlarının nerede tutulacağını ve kişisel verilerin nasıl işleneceğini ayrıca netleştiririz.',
  metrics=[['Başlatılan konuşma', 'Reklamdan sohbete geçen kişi', 'Konuşmanın uygunluğu ayrıca değerlendirilir'], ['İlk yanıt süresi', 'Müşteriye ne kadar sürede dönüldü', 'Çalışma saati ve ekip yapısıyla okunur'], ['Satışa dönen sohbet', 'Sohbetten sipariş çıktı', 'Elle kayıt gerektirir, eksik kalabilir']],
  steps=[('İşletmenizi ve WhatsApp kullanımınızı tanıyalım', 'Müşterilerinizin sizinle nasıl iletişim kurduğunu, bugünkü numaranızı ve ekibinizi dinleriz.'), ('Kapsam ve kuralları netleştirelim', 'Hangi mesajların gönderileceği, izin düzeni ve uygulama mı API mi kullanılacağı yazılı hale getirilir.'), ('Hesapları ve ölçümü kontrol edelim', 'WhatsApp, Meta reklam hesabı ve katalog bağlantıları kontrol edilir; konuşma kayıt düzeni kurulur.'), ('Reklam, katalog ve akışı hazırlayalım', 'Reklam, karşılama mesajı, hazır yanıtlar ve yayın planı hazırlanır; onayınızdan sonra yayına alınır.'), ('Yayın ve ilk değerlendirmeyi yapalım', 'Konuşma sayısı, yanıt süresi ve satış kaydı izlenir; ilk dönem sonunda mesaj ve akış güncellenir.')],
  needs='WhatsApp numaranız, Meta işletme hesabınız (varsa), ürün listesi ve mesajlara bakacak ekip bilgisi yeterli bir başlangıçtır. Şifre paylaşmak yerine yetkilendirme araçlarıyla erişim verilir.',
  scen=[('Hurma ve kuruyemiş satan mağaza için örnek çalışma senaryosu', 'Bir mağaza ürün fiyat ve kargo sorularını tek tek yanıtlıyor. Sık sorulan soruların listesi çıkarılır. Örnek yaklaşımda reklamlar WhatsApp sohbetine yönlendirilir, katalogda ürünler ve hazır yanıtlar düzenlenir. Değerlendirme başlayan konuşmalar, yanıt süresi ve siparişlerle yapılır.'), ('Güzellik salonu için örnek çalışma senaryosu', 'Bir salon randevuları telefonla alıyor ve yoğun saatlerde arama kaçırıyor. Örnek yaklaşımda reklam doğrudan WhatsApp randevu sohbetine yönlendirilir, çalışma saatleri dışı için karşılama mesajı hazırlanır ve hatırlatmalar yalnızca izin veren müşterilere gönderilir.')],
  costRows=[['Reklam bütçesi', 'Meta reklam hesabınıza', 'Kitle ve rekabete göre değişir'], ['Mesaj ücretleri', 'Meta veya sağlayıcıya, API kullanılıyorsa', 'Mesaj türüne ve paket yapısına göre değişir'], ['Yönetim bedeli', 'PakSoft’a', 'Kampanya ve akış kapsamına göre belirlenir'], ['Katalog ve içerik', 'PakSoft veya sizin ekibiniz', 'Ürün sayısı ve görsel ihtiyacı']],
  factors=[('Reklam kapsamı', 'Kampanya ve kitle sayısı'), ('Uygulama veya API', 'API kullanımı entegrasyon işi ve ek maliyet getirir'), ('Katalog büyüklüğü', 'Ürün sayısı ve düzenleme işi'), ('Ekip yanıt kapasitesi', 'Yanıt süresi ve temsilci sayısı'), ('Rapor düzeni', 'Rapor sıklığı ve toplantılar')],
  faq=[('WhatsApp pazarlama nedir?', 'Müşterilerle WhatsApp üzerinden reklam, katalog ve izinli mesajlarla iletişim kurma çalışmasıdır.'), ('Toplu mesaj gönderebilir miyim?', 'Yalnızca izin veren kişilere ve kurallara uygun biçimde. İzinsiz mesaj riskli olabilir.'), ('Uygulama yeterli mi?', 'Küçük hacimde olabilir. Çok temsilci veya otomasyon için API gerekebilir.'), ('Click-to-WhatsApp reklamı nedir?', 'Reklama tıklayan kişiyi WhatsApp sohbetine yönlendiren reklam biçimidir. Güncel seçenekler reklam panelinde görünür.'),
       ('Ne kadar sürede sonuç alırım?', 'Kesin bir tarih veya satış vaat etmeyiz. Süre ürüne ve yanıt hızınıza bağlıdır.'), ('Reklam bütçesi dahil mi?', 'Hayır. Reklam bütçesi Meta’ya, yönetim bedeli PakSoft’a ödenir; mesaj ücretleri varsa ayrıca yazılır.'), ('Müşteri verileri nasıl korunur?', 'Konuşmalarda ve kayıtlarda kişisel veri minimum tutulur. İzin ve saklama düzenini birlikte belirleriz.'), ('Chatbot kurulabilir mi?', 'Evet. Sık sorulara yanıt veren ve karmaşık konuları temsilciye devreden bir akış kurulabilir; bu ayrı kapsamda planlanır.')],
